'use strict';
const $ = id => document.getElementById(id);
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tour = [
  ['01 / OBSERVE','Start with a neighborhood.','Explore the Dubai Action Atlas. Its twelve neighborhood concepts are investigation prompts, not verified intervention sites.','../action-atlas/'],
  ['02 / COMPARE','Test a possible future.','Use the scenario controls to compare proposed trees, canopy area and assumed survival. Read the limits before interpreting the output.','#interventions'],
  ['03 / PROTECT','Make adaptation human.','See how HeatShield could help an outdoor construction worker access heat safety information in a familiar language.','#workers'],
  ['04 / DECIDE','Put money beside carbon.','Use a commute scenario with explicit costs and sourced emission-factor proxies.','#wallet'],
  ['05 / PARTICIPATE','Turn evidence into action.','Return to the Action Atlas to explore opportunities and register conceptual interest, without claiming a real project or verified impact.','../action-atlas/']
];
let tourIndex=0;
function renderTour(){let t=tour[tourIndex]; $('tour-content').innerHTML=`<span>${esc(t[0])}</span><h3>${esc(t[1])}</h3><p>${esc(t[2])}</p>`;$('tour-count').textContent=String(tourIndex+1).padStart(2,'0')+' / 05';$('tour-dots').innerHTML=tour.map((_,i)=>`<button type="button" data-step="${i}" class="${i===tourIndex?'current':''}" aria-label="Go to walkthrough step ${i+1}" aria-current="${i===tourIndex?'step':'false'}"></button>`).join('');$('tour-link').href=t[3];$('tour-prev').disabled=tourIndex===0;$('tour-next').textContent=tourIndex===4?'Restart tour ↺':'Next step →';}
$('tour-prev').onclick=()=>{tourIndex=Math.max(0,tourIndex-1);renderTour()};$('tour-next').onclick=()=>{tourIndex=(tourIndex+1)%tour.length;renderTour()};$('tour-dots').addEventListener('click',e=>{let b=e.target.closest('button[data-step]');if(b){tourIndex=Number(b.dataset.step);renderTour()}});renderTour();
function updateScenario(){let trees=+$('tree-count').value,area=+$('canopy-area').value,survival=+$('survival').value/100,width=+$('corridor-width').value;const corridor=200*width, canopy=trees*area*survival, coverage=Math.min(100,100*canopy/corridor);$('tree-count-val').textContent=trees;$('canopy-area-val').textContent=area+' m²';$('survival-val').textContent=Math.round(survival*100)+'%';$('corridor-width-val').textContent=width+' m';$('canopy-result').textContent=Math.round(canopy).toLocaleString()+' m²';$('shade-result').textContent=coverage.toFixed(1)+'%';$('scenario-explain').textContent=`${trees} trees × ${area} m² assumed canopy × ${Math.round(survival*100)}% effective survival ÷ ${corridor.toLocaleString()} m² corridor = ${coverage.toFixed(1)}% theoretical coverage. Canopies overlap; this simplified fraction does not model shadows, seasonal growth, groundwater, pedestrian comfort or air temperature.`;const count=Math.min(12,Math.ceil(trees/3));$('street-trees').innerHTML=Array.from({length:count},()=>'<span class="tree"></span>').join('')}
['tree-count','canopy-area','survival','corridor-width'].forEach(id=>$(id).addEventListener('input',updateScenario));updateScenario();
function localTodayDubai(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dubai',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=k=>parts.find(p=>p.type===k).value;return `${get('year')}-${get('month')}-${get('day')}`}
$('worker-date').value=localTodayDubai();
const workerCopy={
 en:{restricted:'Scheduled direct-sun outdoor work falls within the UAE midday restriction.',general:'The seasonal midday restriction may not apply to this time and setting, but heat stress can still be dangerous.',base:'From 15 June to 15 September, outdoor work in direct sunlight/open areas is generally prohibited 12:30–15:00, subject to specific exceptions. Contact a supervisor and follow official workplace procedures. This is not a workplace compliance determination.',other:'Follow your employer’s heat-stress procedures, rest and cooling provisions. Indoor, shaded or exempt work may still have heat risks.'},
 bn:{restricted:'এই সময়ে সরাসরি রোদে বাইরের কাজের ওপর সংযুক্ত আরব আমিরাতের মধ্যাহ্নকালীন নিষেধাজ্ঞা সাধারণভাবে প্রযোজ্য।',general:'এই সময়ে মধ্যাহ্নকালীন নিষেধাজ্ঞা প্রযোজ্য নাও হতে পারে, তবে গরমে অসুস্থতার ঝুঁকি থাকতে পারে।',base:'১৫ জুন থেকে ১৫ সেপ্টেম্বর, সাধারণভাবে দুপুর ১২:৩০ থেকে ৩:০০ পর্যন্ত খোলা জায়গায় সরাসরি রোদে কাজ নিষিদ্ধ; কিছু নির্দিষ্ট ব্যতিক্রম রয়েছে। সুপারভাইজারের সঙ্গে যোগাযোগ করুন এবং সরকারি নিয়ম অনুসরণ করুন।',other:'কর্মস্থলের তাপ-সুরক্ষা নির্দেশনা অনুসরণ করুন এবং বিশ্রাম ও ঠান্ডা স্থানের ব্যবস্থা নিশ্চিত করুন।'},
 ar:{restricted:'يقع العمل الخارجي تحت الشمس المباشرة في فترة حظر العمل وقت الظهيرة في الإمارات.',general:'قد لا ينطبق حظر الظهيرة على هذا الوقت أو المكان، لكن الإجهاد الحراري يظل خطراً.',base:'من 15 يونيو إلى 15 سبتمبر، يُحظر عموماً العمل في الأماكن المكشوفة تحت أشعة الشمس من 12:30 إلى 15:00، مع استثناءات محددة. تواصل مع المشرف واتبع الإرشادات الرسمية.',other:'اتبع إجراءات السلامة من الحرارة في العمل وتأكد من توفر الراحة والظل والتبريد.'}
};
$('worker-form').addEventListener('submit',e=>{e.preventDefault();const lang=$('worker-language').value, copy=workerCopy[lang], day=$('worker-date').value,hm=$('worker-hour').value,setting=$('worker-type').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(day)||!/^\d{2}:\d{2}$/.test(hm)){return}const monthDay=day.slice(5),minutes=Number(hm.slice(0,2))*60+Number(hm.slice(3)),season=monthDay>='06-15'&&monthDay<='09-15',time=minutes>=750&&minutes<900,restricted=season&&time&&setting==='outdoor';$('worker-headline').textContent=restricted?copy.restricted:copy.general;$('worker-message').textContent=restricted?copy.base:copy.other;$('worker-safety').textContent=restricted?'IMPORTANT: General midday-break restriction indicated for this selected schedule. Certain authorized exceptions exist. Employer-led safety controls are still necessary. Seek official guidance; do not use this prototype to decide if work may proceed.':'IMPORTANT: This tool does not determine workplace safety. Work outside the restricted hours can still cause heat illness. Supervisors must assess actual exposure and provide safeguards.';$('worker-message').lang=lang;$('worker-headline').lang=lang;});
const factor={car:.16591,bus:.10151,rail:.02121,walk:0};
$('wallet-form').addEventListener('submit',e=>{e.preventDefault();let km=+$('wallet-distance').value,days=+$('wallet-days').value,cur=$('wallet-current').value,alt=$('wallet-alternative').value,c0=+$('wallet-cost-current').value,c1=+$('wallet-cost-alt').value;if(!(km>.0&&km<=150&&days>=1&&days<=31&&c0>=0&&c1>=0))return;let money=(c0-c1)*days,carbon=km*2*days*(factor[cur]-factor[alt]);$('wallet-money').textContent=(money>=0?'+':'−')+Math.abs(money).toFixed(0)+' AED';$('wallet-carbon').textContent=(carbon>=0?'+':'−')+Math.abs(carbon).toFixed(1)+' kg';$('wallet-message').textContent=`For ${days} round-trip days (${(2*km*days).toFixed(0)} km), the alternative ${money>=0?'saves':'costs an additional'} ${Math.abs(money).toFixed(0)} AED and ${carbon>=0?'avoids':'adds'} about ${Math.abs(carbon).toFixed(1)} kg operational CO₂e under UK proxy factors. Neither fares nor these emissions factors are verified Dubai route values.`;});
const homeGuidance=[
 ['home-heat','Ask the building manager about overheating mitigation and ventilation; avoid unverified cooling claims.'],
 ['home-shade','Investigate removable shading or curtains suitable for your tenancy and building rules.'],
 ['home-water','Document previous water entry and request a property drainage and waterproofing inspection.'],
 ['home-drains','Ask for a drainage inspection and maintenance, especially before heavy rain.'],
 ['home-power','Ask a qualified electrician to assess any electrical outlet exposed to water; do not modify wiring yourself.']
];
$('home-form').addEventListener('submit',e=>{e.preventDefault();let items=homeGuidance.map(([id,msg])=>({risk:Number($(id).value),msg})).filter(x=>x.risk>0).sort((a,b)=>b.risk-a.risk);const score=homeGuidance.reduce((sum,[id])=>sum+Number($(id).value),0);$('home-headline').textContent=score===0?'No concerns reported in this quick checklist.':`${items.length} area${items.length>1?'s':''} to investigate.`;$('home-recommendations').innerHTML=(items.length?items:[{msg:'Continue routine maintenance and periodic checks; this checklist does not confirm that the home is climate-proof.'}]).map(x=>'<li>'+esc(x.msg)+'</li>').join('');});
function parseFood(text){const foods=[];for(const ln of text.split(/\n/).slice(0,30)){const raw=ln.trim();if(!raw)continue;let pieces=raw.split(',');let date=pieces.length>1?pieces[pieces.length-1].trim():'';let name=pieces.length>1?pieces.slice(0,-1).join(',').trim():raw;let valid=/^\d{4}-\d{2}-\d{2}$/.test(date)&&!Number.isNaN(new Date(date+'T00:00:00Z').getTime());foods.push({name:name.slice(0,80),date:valid?date:null})}return foods.sort((a,b)=>a.date&&b.date?a.date.localeCompare(b.date):a.date?-1:b.date?1:0)}
$('fridge-form').addEventListener('submit',e=>{e.preventDefault();const foods=parseFood($('fridge-items').value),today=localTodayDubai();$('fridge-results').innerHTML=foods.length?foods.map(item=>{let note=!item.date?'no date supplied':item.date<today?'date already passed — check safety before any use':item.date===today?'dated today — check use-by and storage':'dated '+item.date;return `<li><strong>${esc(item.name)}</strong> — ${esc(note)}</li>`}).join(''):'<li>Add ingredients to see a priority list.</li>';const s=foods.map(x=>x.name.toLowerCase()).join(' ');let idea=/tomato|spinach|onion|pepper|eggplant/.test(s)?'Meal idea: sauté suitable fresh vegetables and serve over rice or with eggs, if safely stored and appropriate.':/rice|lentil|bean/.test(s)?'Meal idea: consider a simple grain-and-legume bowl with any fresh produce available.':'Meal idea: combine compatible, safely stored ingredients into a soup, stir-fry or sandwich.';$('fridge-idea').textContent=foods.length?idea:'Simple meal inspiration appears when recognizable ingredients are supplied.'});
const qs={flood:['Does the policy cover rainwater ingress, surface flooding and sewer backup separately?','Are there waiting periods, excesses, sublimits or proof requirements?','Does it cover temporary accommodation or business interruption?'],storm:['How does the policy define windstorm and the minimum event threshold?','What are the exclusions for roof, window or maintenance-related damage?','What evidence and claim deadlines would apply after a storm?'],heat:['Is heat-related equipment failure, spoilage or interruption covered at all?','Does the insurer require a named insured physical damage trigger?','Would any parametric product pay based on an index, and which exact trigger and exclusions apply?']};
$('insurance-form').addEventListener('submit',e=>{e.preventDefault();let risk=$('insurance-risk').value,profile=$('insurance-profile').value;let prefix=profile==='renter'?'Ask separately about contents versus landlord building coverage.':profile==='owner'?'Ask about building versus personal contents limits.':'Ask about covered physical damage and any business-interruption conditions.';$('insurance-results').innerHTML=[prefix,...qs[risk]].map(x=>'<li>'+esc(x)+'</li>').join('')});
